from collections import deque
def comps(G,bg):
    R,C=len(G),len(G[0]); seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if G[r][c]!=bg and (r,c) not in seen:
                col=G[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<R and 0<=y<C and (x,y) not in seen and G[x][y]==col:
                            seen.add((x,y)); q.append((x,y))
                out.append((col,cells))
    return out

