def shape_key(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,c0=min(rs),min(cs)
    norm=frozenset((r-r0,c-c0) for r,c in cells)
    # canonical under rotations/reflections
    variants=[]
    for t in [norm,
              frozenset((c,-r) for r,c in norm),
              frozenset((-r,-c) for r,c in norm),
              frozenset((-c,r) for r,c in norm)]:
        mr=min(r for r,c in t); mc=min(c for r,c in t)
        variants.append(frozenset((r-mr,c-mc) for r,c in t))
    return min(variants, key=lambda s: sorted(s))

